-- SIG CSA-TIC | Almoxarifado: projeção de consulta segregada do controle financeiro.
-- Origem: DESTINACAO_REPASSES da PLANILHA ATUAL (RIPC), 19/10/2026.
-- A classificação RPM exige menção explícita na coluna Destino, sem geocodificação presumida.
-- Entrega, quantidade e data de aquisição não estão disponíveis na fonte RIPC e não são inferidas.
CREATE TABLE IF NOT EXISTS public.sig_almox_destinacoes (
 chave_origem text PRIMARY KEY,
 chave_repasse text,
 ano integer NOT NULL CHECK (ano BETWEEN 2000 AND 2100),
 documento_repasse text,
 processo_origem text,
 material_descricao text,
 unidade_destinataria text,
 rpm smallint CHECK (rpm BETWEEN 1 AND 19),
 valor_ripc numeric(18,2) CHECK (valor_ripc>=0),
 data_registro date,
 situacao_processo text,
 validacao_origem text,
 quantidade numeric,
 situacao_entrega text,
 data_aquisicao date,
 atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.sig_almox_destinacoes IS 'Projeção de consulta RIPC; processo de compra NÃO comprova entrega, aquisição concluída nem quantitativo. Só RPM textualmente explícita é classificada.';
CREATE INDEX IF NOT EXISTS sig_almox_por_rpm_ano ON public.sig_almox_destinacoes(rpm,ano);
ALTER TABLE public.sig_almox_destinacoes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sig_almox_destinacoes FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.sig_almox_destinacoes TO authenticated;
CREATE POLICY sig_almox_leitura ON public.sig_almox_destinacoes
 FOR SELECT TO authenticated USING (private.can_view_cota());
ON CONFLICT (chave_origem) DO NOTHING;
